mapper.sql:
WHERE snapshot_ym = #{snapshotYm}
  AND net_assets BETWEEN #{netAssetsMin} AND #{netAssetsMax}
  AND age        BETWEEN #{ageMin}       AND #{ageMax}

  AND monthly_income BETWEEN #{monthlyIncomeMin} AND #{monthlyIncomeMax}


  AND occupation_type = #{occupationType}

mapper.select:
SELECT EXISTS(
    SELECT 1 FROM goal
    WHERE member_id = #{memberId}
      AND status = 'ACTIVE'
      AND target_amount > 0
)
